public sealed class GenerationDresserFraming1458Tests
{
    public static IEnumerable<object[]> OriginalCases()
    {
        using var stream=new GZipStream(new MemoryStream(Convert.FromBase64String(OriginalData)),CompressionMode.Decompress);using var reader=new StreamReader(stream);
        while(reader.ReadLine()is{}line){var p=line.Split('\t');yield return new object[]{int.Parse(p[0]),int.Parse(p[1]),int.Parse(p[2]),int.Parse(p[3]),int.Parse(p[4]),p[5]=="1",p[6],p[7],p[8]};}
    }
    [Theory]
    [MemberData(nameof(OriginalCases))]
    public void Actual_original_dresser_kills_and_framing_match_tiles_rng_and_ordered_chest_file_projection(int seed,int style,int member,int damage,int metadata,bool kill,string grid,string rng,string chestHash)
    {
        var w=new Workspace(80,80);Assert.True(w.TileStore.TryAttachTileEntities([],1000));
        void Cell(int x,int y,ushort type,int frameX,int frameY)=>w.TileStore.Set(x,y,new(){Type=type,Flags=WorldTileFlags.Active|WorldTileFlagMasks.Wires|WorldTileFlags.Actuator|WorldTileFlagMasks.Visibility|WorldTileFlagMasks.Fullbright,FrameX=(short)frameX,FrameY=(short)frameY,Wall=15,TileColor=7,WallColor=9});
        for(int column=0;column<3;column++){for(int row=0;row<2;row++)Cell(30+column,30+row,88,style*54+column*18,row*18);Cell(30+column,32,1,0,0);}
        void Chest(int x,int y,string name,bool filled)
        {
            if(x!=30)for(int column=0;column<2;column++)for(int row=0;row<2;row++)Cell(x+column,y+row,21,column*18,row*18);
            Assert.True(w.TryAddGeneratedChest(x,y,name,filled?[new WorldChestItem(1,8,0)]:[]));
        }
        if(metadata==3)Chest(12,12,"left",true);if(metadata!=0)Chest(30,30,"subject",metadata==2);if(metadata==3)Chest(60,12,"right",true);
        ref var changed=ref w.TileStore.Tiles[w.TileStore.GetUncheckedIndex(32,31)];
        if(damage==1)changed.Flags&=~WorldTileFlags.Active;if(damage==2)changed.Type=1;if(damage==3){changed.Flags&=~WorldTileFlags.Active;changed.Type=1;}if(damage==4)changed.FrameX+=18;if(damage==5)changed.FrameY=0;
        ref var ground=ref w.TileStore.Tiles[w.TileStore.GetUncheckedIndex(31,32)];
        if(damage==6)ground.Flags&=~WorldTileFlags.Active;if(damage==7)ground.TrySetSourceShape(true,0);if(damage==8)ground.TrySetSourceShape(true,4);if(damage==9)ground.TrySetSourceShape(false,1);if(damage==11)ground.Flags|=WorldTileFlags.Inactive;
        if(damage is 10 or 12)for(int x=30;x<33;x++)for(int y=30;y<32;y++){ref var t=ref w.TileStore.Tiles[w.TileStore.GetUncheckedIndex(x,y)];if(damage==10)t.Flags|=WorldTileFlags.Inactive;else{t.LiquidAmount=255;t.LiquidKind=WorldLiquidKind.Lava;}}
        var random=new DresserRandom(seed);var framing=new GenerationTileFraming1458(w.TileStore,random,w);int tx=30+member/2,ty=30+member%2;if(kill)framing.KillTile(tx,ty);else framing.TileFrame(tx,ty,true);
        using var bytes=new MemoryStream();using(var writer=new BinaryWriter(bytes))for(int x=0;x<80;x++)for(int y=0;y<80;y++){var t=w.TileStore.Get(x,y);writer.Write(t.Type);writer.Write(t.Wall);writer.Write(t.FrameX);writer.Write(t.FrameY);writer.Write(t.LiquidAmount);writer.Write((byte)t.LiquidKind);writer.Write(t.Shape);writer.Write(t.TileColor);writer.Write(t.WallColor);writer.Write((ushort)t.Flags);}
        Assert.Equal(grid,Convert.ToHexString(SHA256.HashData(bytes.ToArray())));
        using var state=new MemoryStream();using(var writer=new BinaryWriter(state)){writer.Write((uint)typeof(VanillaUnifiedRandom1458).GetField("inext",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(random.Source)!);foreach(int value in(int[])typeof(VanillaUnifiedRandom1458).GetField("seedArray",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(random.Source)!)writer.Write(value);}
        Assert.Equal(rng,Convert.ToHexString(SHA256.HashData(state.ToArray())));
        var chests=w.CaptureGeneratedChests().Select(c=>new{c.X,c.Y,c.Name,Items=c.Items.Select(i=>new{i.Stack,i.ItemType,i.Prefix}).ToArray()}).ToArray();
        Assert.Equal(chestHash,Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(chests)))));
    }
    private sealed class DresserRandom(int seed):IWorldGenerationVanillaRandom
    {
        internal readonly VanillaUnifiedRandom1458 Source=new(seed);
        public int Next()=>Source.Next();public int Next(int max)=>Source.Next(max);public int Next(int min,int max)=>Source.Next(min,max);public double NextDouble()=>Source.NextDouble();public void NextBytes(byte[] bytes)=>Source.NextBytes(bytes);
    }
